def solve_n(n):
    cols=set();diag1=set();diag2=set()
    res=[-1]*n
    def back(r):
        if r==n:
            return True
        for c in range(n):
            if c in cols or (r-c) in diag1 or (r+c) in diag2:
                continue
            cols.add(c);diag1.add(r-c);diag2.add(r+c);res[r]=c
            if back(r+1):
                return True
            cols.remove(c);diag1.remove(r-c);diag2.remove(r+c)
        return False
    return res if back(0) else None
